 private void loadMessages(){final String target=activeId;if(target==null)return;io.execute(()->{try{HttpResult r=request("GET","/api/messages/"+URLEncoder.encode(target,"UTF-8"),null,auth());if(r.code==200){JSONArray a=new JSONObject(r.body).optJSONArray("messages");h.post(()->{if(target.equals(activeId))render(a);});}}catch(Exception ignored){}});}
 private void render(JSONArray a){if(messages==null)return;messages.removeAllViews();String meW=prefs.getString(ID,"");String meDb=prefs.getString("db_user_id","");if(a==null||a.length()==0){messages.addView(tv("ابدأ المحادثة الآن",17,Color.GRAY));return;}for(int i=0;i<a.length();i++){JSONObject m=a.optJSONObject(i);if(m==null)continue;String s=m.optString("sender_id"),senderW=m.optString("sender_wethaq_id"),senderName=m.optString("sender_name","مستخدم");String type=m.optString("message_type","text");boolean mine=meW.equals(senderW)||meDb.equals(s);LinearLayout line=new LinearLayout(this);line.setOrientation(LinearLayout.HORIZONTAL);line.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);ImageView av=new ImageView(this);av.setScaleType(ImageView.ScaleType.CENTER_CROP);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(44),dp(44));ap.setMargins(dp(4),dp(4),dp(4),dp(4));av.setLayoutParams(ap);if(!senderW.isEmpty())loadAvatarInto(senderW,av);line.addView(av);LinearLayout bubble=new LinearLayout(this);bubble.setOrientation(LinearLayout.VERTICAL);bubble.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);TextView name=tv(mine?"أنت":senderName,17,mine?gold():Color.WHITE);name.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);bubble.addView(name);if("image".equals(type)){ImageView im=new ImageView(this);im.setAdjustViewBounds(true);im.setMaxHeight(dp(280));im.setScaleType(ImageView.ScaleType.CENTER_INSIDE);try{byte[] z=Base64.getDecoder().decode(m.optString("audio_data"));im.setImageBitmap(BitmapFactory.decodeByteArray(z,0,z.length));}catch(Exception e){}bubble.addView(im);}else if("audio".equals(type)){TextView b=tv("▶ رسالة صوتية",19,Color.WHITE);String data=m.optString("audio_data");b.setOnClickListener(v->playAudio(data));bubble.addView(b);}else{TextView b=tv(m.optString("body",m.optString("text")),19,mine?Color.BLACK:Color.WHITE);b.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);bubble.addView(b);TextView st=tv(mine?"✓✓":"✓",14,mine?Color.BLACK:Color.LTGRAY);st.setGravity(mine?Gravity.RIGHT:Gravity.LEFT);bubble.addView(st);}GradientDrawable d=new GradientDrawable();d.setColor(mine?gold():Color.rgb(32,32,32));d.setCornerRadius(dp(14));bubble.setPadding(dp(12),dp(8),dp(12),dp(8));bubble.setBackground(d);line.addView(bubble,new LinearLayout.LayoutParams(0,-2,1));messages.addView(line,lp(-1,-2,8));}}
 private void addLocalContact(String id,String name){try{if(id==null||id.isEmpty())return;JSONArray a=contacts();for(int i=0;i<a.length();i++)if(id.equals(a.optJSONObject(i).optString("wethaq_id")))return;JSONObject o=new JSONObject();o.put("wethaq_id",id);o.put("name",name==null?"مستخدم":name);a.put(o);prefs.edit().putString(CONTACTS,a.toString()).apply();}catch(Exception ignored){}}
 private void send(){
 final String target=activeId;if(target==null||target.trim().isEmpty())return;
 if(pendingAudioData!=null&&!pendingAudioData.isEmpty()){final String data=pendingAudioData;final String mime=pendingMime==null?"audio/mp4":pendingMime;io.execute(()->{try{JSONObject q=new JSONObject();q.put("to",target);q.put("audioBase64",data);q.put("mimeType",mime);HttpResult r=request("POST","/api/messages/audio",q.toString(),auth());h.post(()->{if(r.code>=200&&r.code<300){pendingAudioData=null;pendingMime=null;pendingMediaType=0;clearComposerMedia();loadMessages();toast("تم إرسال التسجيل الصوتي ✓");}else toast(error(r));});}catch(Exception e){h.post(()->toast("فشل إرسال التسجيل الصوتي"));}});return;}
 if(pendingImageData!=null&&!pendingImageData.isEmpty()){final String data=pendingImageData;final String mime=pendingMime==null?"image/jpeg":pendingMime;io.execute(()->{try{JSONObject q=new JSONObject();q.put("to",target);q.put("imageBase64",data);q.put("mimeType",mime);HttpResult r=request("POST","/api/messages/image",q.toString(),auth());h.post(()->{if(r.code>=200&&r.code<300){pendingImageData=null;pendingMime=null;pendingMediaType=0;clearComposerMedia();loadMessages();toast("تم إرسال الصورة ✓");}else toast(error(r));});}catch(Exception e){h.post(()->toast("فشل إرسال الصورة"));}});return;}
 String text=input==null?"":input.getText().toString().trim();if(text.isEmpty())return;io.execute(()->{try{JSONObject q=new JSONObject();q.put("to",target);q.put("body",text);HttpResult r=request("POST","/api/messages",q.toString(),auth());h.post(()->{if(r.code>=200&&r.code<300){input.setText("");loadMessages();}else toast(error(r));});}catch(Exception e){h.post(()->toast("فشل الإرسال"));}});
}
