 private void sendComplaint(){base("الشكاوى والتواصل مع المؤسس");TextView info=tv("اكتب شكواك أو رسالتك للمؤسس ثم اضغط إرسال.",18,Color.WHITE);info.setGravity(Gravity.CENTER);EditText box=field("اكتب الشكوى هنا…");box.setSingleLine(false);box.setMinHeight(dp(180));box.setGravity(Gravity.TOP|Gravity.RIGHT);Button send=btn("إرسال الشكوى"),back=btn("رجوع");content.addView(info,lp(-1,-2,12));content.addView(box,lp(-1,190,12));content.addView(send,lp(-1,76,8));content.addView(back,lp(-1,76,8));send.setOnClickListener(v->{click();String msg=box.getText().toString().trim();if(msg.length()<2){toast("اكتب الشكوى أولاً");return;}io.execute(()->{try{JSONObject q=new JSONObject();q.put("message",msg);HttpResult r=request("POST","/api/complaints",q.toString(),auth());h.post(()->toast(r.code>=200&&r.code<300?"تم إرسال الشكوى إلى المؤسس ✓":error(r)));}catch(Exception e){h.post(()->toast("تعذر إرسال الشكوى"));}});});back.setOnClickListener(v->{click();home();});}
